from pathlib import Path
p=Path('docs/qa/callgraph-viewer/index.html')
s=p.read_text()
s=s.replace('.failure{color:', '.audit{margin-top:20px;border-top:1px solid #d5bf99;padding-top:16px}.audit p,.audit li{overflow-wrap:anywhere}.badge{font-size:12px;fill:#684921}.static-sites{font-size:14px}.static-sites li{margin:8px 0}.failure{color:')
s=s.replace('<h2>Таблица методов</h2>', '<h2>Отчёт по оптимизации</h2><p>Разбор каждого измеренного метода: математическая эквивалентность, риски и необходимые проверки. Предложение не означает доказанного ускорения. Статические упоминания исходника показаны отдельно от связей, наблюдавшихся в прогоне.</p><div id="auditStatus" class="meta">Загрузка отчёта…</div><div class="tablewrap"><table><thead><tr><th>Метод</th><th>Приоритет</th><th>Статус</th><th>Предложение</th></tr></thead><tbody id="audits"></tbody></table></div><h2>Таблица методов</h2>')
s=s.replace('let D,selected=null;', 'let D,A=null,selected=null;')
s=s.replace("g.addEventListener('click',()=>choose(n.id));", "const audit=A?.methods.find(a=>a.id===n.id);if(audit)g.append(el('text',{'text-anchor':'middle',y:101,class:'badge'},audit.priority+' · '+statusLabel(audit.status)));g.addEventListener('click',()=>choose(n.id));")
s=s.replace("$('detail').append(list)}render()}", "$('detail').append(list)}showAudit(id);render()}")
pos=s.index("fetch('data.json')")
s=s[:pos]+'''function statusLabel(s){return ({proposal:'Предложение',hypothesis:'Гипотеза','no-change':'Без изменения','no-justified-change':'Без изменения',validated:'Проверено'})[s]||s}
function sourceLink(source){const a=document.createElement('a');a.href='https://github.com/SuselMan/art_lessons/blob/6aa14a43/'+source.path+'#L'+source.line;a.textContent=source.path+':'+source.line;a.target='_blank';a.rel='noopener noreferrer';return a}
function paragraph(parent,title,value){if(!value)return;const p=document.createElement('p'),b=document.createElement('b');b.textContent=title+': ';p.append(b,document.createTextNode(typeof value==='string'?value:JSON.stringify(value)));parent.append(p)}
function showAudit(id){const a=A?.methods.find(a=>a.id===id),box=document.createElement('div');box.className='audit';if(!a){box.textContent=A?'Для этого метода нет отчёта.':'Отчёт по оптимизации ещё не загружен.';$('detail').append(box);return}paragraph(box,'Статус',statusLabel(a.status)+' · '+a.priority);if(a.source){const p=document.createElement('p');p.append('Определение метода: ',sourceLink(a.source));box.append(p)}paragraph(box,'Назначение',a.purpose||a.summary);paragraph(box,'Сложность',a.complexity);for(const proposal of a.proposals||[]){const h=document.createElement('h4');h.textContent=proposal.title;box.append(h);paragraph(box,'Почему быстрее',proposal.rationale);paragraph(box,'Что обязано остаться одинаковым',proposal.qualityInvariant);paragraph(box,'Риск',proposal.risk);paragraph(box,'Как доказать',proposal.validation)}paragraph(box,'Предложение',a.optimization);paragraph(box,'Эквивалентность',a.equivalence);paragraph(box,'Риски',a.risks);paragraph(box,'Проверка',a.validation);const sites=a.callsites||a.callers||[];if(sites.length){const h=document.createElement('h4');h.textContent='Статические упоминания в исходнике';box.append(h);paragraph(box,'Смысл списка','Поиск в коде, не измеренные вызовы. Упоминание может быть вызовом, передачей callback или доступом к методу; количество строк не равно частоте исполнения.');const ul=document.createElement('ul');ul.className='static-sites';for(const site of sites){const li=document.createElement('li');li.append(sourceLink(site),document.createTextNode(site.caller?' · '+site.caller:''));ul.append(li)}box.append(ul)}$('detail').append(box)}
fetch('method-audit.json').then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json()}).then(a=>{A=a;$('auditStatus').textContent=a.methods.length+' методов разобрано. Все предложения требуют проверки на одинаковых входах; внедрение не выполнялось.';for(const n of a.methods){const tr=document.createElement('tr');for(const value of [n.id,n.priority,statusLabel(n.status),(n.proposals||[]).map(p=>p.title).join('; ')||n.optimization||'Изменение не обосновано']){const td=document.createElement('td');td.style.whiteSpace='normal';if(value===n.id){const b=document.createElement('button');b.textContent=n.id;b.onclick=()=>choose(n.id);td.append(b)}else td.textContent=value;tr.append(td)}$('audits').append(tr)}if(D){if(selected)choose(selected);else render()}}).catch(e=>{$('auditStatus').textContent='Отчёт пока недоступен: '+e;});
''' +s[pos:]
p.write_text(s)
